parts.text:
{
  "conversations": [
    {
      "title": "Accept or decline a dance",
      "lines": [
        { "speaker": "partner", "text": "Wanna dance?" },
        { "speaker": "you", "text": "I'd love to." },
        { "speaker": "you", "text": "Maybe later.", "or": true },
        { "speaker": "partner", "text": "Awesome." },
        { "speaker": "partner", "text": "No worries.", "or": true }
      ]
    },
    {
      "title": "Compliment someone's dancing",
      "lines": [
        { "speaker": "you", "text": "You're a great dancer." },
        { "speaker": "partner", "text": "Thanks so much." },
        { "speaker": "you", "text": "I'm still learning." },
        { "speaker": "partner", "text": "You're doing fine." },
        { "speaker": "partner", "text": "Keep it up.", "or": true }
      ]
    },
    {
      "title": "Chat between songs",
      "lines": [
        { "speaker": "partner", "text": "Come here often?" },
        { "speaker": "you", "text": "Not really." },
        { "speaker": "you", "text": "Every weekend.", "or": true },
        { "speaker": "partner", "text": "I'm loving this music." },
        { "speaker": "you", "text": "Me too." },
        { "speaker": "partner", "text": "See you around." }
      ]
    }
  ],
  "vocab": [
    "dance",
    "music",
    "beginner",
    "great",
    "awesome",
    "weekend",
    "lead",
    "follow",
    "step",
    "rhythm",
    "fun",
    "good"
  ]
}
